function mapLabels(entries, mapper, options) {
  const concurrency = options.concurrency;

  if (
    !Number.isInteger(concurrency) ||
    concurrency < 1 ||
    concurrency > 3
  ) {
    return Promise.reject(new RangeError("concurrency must be an integer from 1 to 3"));
  }

  const signal = options.signal;

  if (signal.aborted) {
    return Promise.reject(signal.reason);
  }

  const items = Array.from(entries);

  return new Promise((resolve, reject) => {
    const results = new Array(items.length);
    let nextIndex = 0;
    let active = 0;
    let completed = 0;
    let settled = false;

    const finishReject = (reason) => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", onAbort);
      reject(reason);
    };

    const finishResolve = () => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", onAbort);
      resolve(new Map(items.map(([key], index) => [key, results[index]])));
    };

    const onAbort = () => {
      finishReject(signal.reason);
    };

    const runNext = () => {
      if (settled) return;

      while (
        !settled &&
        active < concurrency &&
        nextIndex < items.length
      ) {
        const index = nextIndex++;
        const [key, value] = items[index];
        let result;

        active++;

        try {
          result = mapper(value, key);
        } catch (error) {
          active--;
          finishReject(error);
          return;
        }

        Promise.resolve(result).then(
          (resolved) => {
            active--;

            if (settled) return;

            results[index] = resolved;
            completed++;

            if (completed === items.length) {
              finishResolve();
            } else {
              runNext();
            }
          },
          (error) => {
            active--;
            finishReject(error);
          }
        );
      }

      if (!settled && items.length === 0) {
        finishResolve();
      }
    };

    signal.addEventListener("abort", onAbort);

    if (signal.aborted) {
      finishReject(signal.reason);
      return;
    }

    runNext();
  });
}
